import type { Lesson } from "@/lib/lessons";

type QuizQuestion = NonNullable<Lesson["questions"]>[number];
type Options = [string, string, string, string];

function q(q: string, options: Options, answer: number, why: string): QuizQuestion {
  return { q, options, answer, why };
}

function lesson(
  topicId: string,
  titleFallback: string,
  overview: string,
  keyPoints: string[],
  practice: string,
  resourceTitle: string,
  resourceUrl: string,
  questions: QuizQuestion[]
): Lesson {
  return {
    topicId,
    titleFallback,
    overview,
    keyPoints,
    practice: [practice],
    resources: [{ title: resourceTitle, url: resourceUrl, source: "Official documentation" }],
    questions,
  };
}

